/**
 * Runtime configuration.
 *
 * `/config.js` is generated by the container at startup (see docker-entrypoint.d) and sets
 * `window.APP_CONFIG`, so the same image can be used with Docker Compose, Kubernetes and
 * OpenShift. Every value is optional.
 */
const configured = window.APP_CONFIG ?? {};

export const config = {
    environment: configured.environment || "Local",
    links: {
        apiDocs: configured.links?.apiDocs || "/api/docs",
        grafana: configured.links?.grafana || "",
        prometheus: configured.links?.prometheus || "",
        argocd: configured.links?.argocd || "",
        ollama: configured.links?.ollama || "",
        postgres: configured.links?.postgres || "",
    },
};
